async function capture(page:Page,info:any,name:string,width:number,language:string,scope='.main-content'){
 const node=page.locator(scope);await expect(node).toBeVisible();expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width);expect(await node.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true);
 await page.evaluate(()=>{(document.activeElement as HTMLElement)?.blur();window.scrollTo(0,0);});await expect.poll(()=>page.evaluate(()=>window.scrollY)).toBe(0);
 await page.screenshot({path:info.outputPath(`${name}-${language}-${width}.png`),fullPage:scope==='.main-content',animations:'disabled'});
}
