 let child:import('node:child_process').ChildProcess,base='',token='',port=0,httpRecord='';let nativeFixture:NativeOperatorFixture;
 const control=async(path:string,method='GET')=>{const response=await fetch(base+path,{method,headers:{'X-Local-Fixture':'operator-audit'}});expect(response.ok).toBe(true);return response.json();};
 test.beforeAll(async()=>{
  const {spawn}=await import('node:child_process'),{default:path}=await import('node:path'),{writeFileSync}=await import('node:fs'),{randomUUID}=await import('node:crypto'),root=path.resolve(process.cwd(),'..'),require=createRequire(import.meta.url);
  child=spawn(process.execPath,[path.join(root,'backend/node_modules/tsx/dist/cli.mjs'),path.join(root,'backend/test/operator_audit.test.ts'),'--browser-server'],{cwd:path.join(root,'backend'),env:require(path.join(root,'scripts/local_check_runtime.cjs')).localCheckEnvironment(root),stdio:['ignore','pipe','pipe'],windowsHide:true});
  const ready=await new Promise<any>((resolve,reject)=>{let output='';const timer=setTimeout(()=>reject(Error('Owned audit fixture not ready')),20000);child.once('error',()=>{clearTimeout(timer);reject(Error('Owned audit fixture failed'));});child.once('exit',()=>{clearTimeout(timer);reject(Error('Owned audit fixture exited'));});child.stdout!.on('data',bytes=>{output+=bytes.toString();const line=output.split(/\r?\n/).find(v=>v.startsWith('{"localFixture"'));if(line){clearTimeout(timer);resolve(JSON.parse(line));}});});
  expect(ready.isolated).toBe(true);port=ready.port;base='http://127.0.0.1:'+port;httpRecord=path.join(root,'.cache/operator-audit-http-'+randomUUID()+'.json');writeFileSync(httpRecord,JSON.stringify({layer:'LOCAL_UI_NATIVE_HTTP_BRIDGE',acceptanceEligible:false,pid:child.pid,fixturePid:ready.pid,port,isolated:true,stopped:false}));
 });
